{
  "cards": [
    {
      "node_code": "N_46fe45aebea7ade5",
      "definition": "研究热处理过程中的热力学与动力学基础，涵盖加热冷却规律、相变机制、微观组织演化机理及由此产生的性能调控与缺陷形成原理。",
      "boundary": "聚焦于解释“为什么”和“如何发生”的理论层面，包括相图应用、扩散方程、形核长大动力学及残余应力产生机理。不侧重具体材料（如钢或铝）的特定工艺参数设定，也不涉及热处理炉具的机械设计或生产流程管理。",
      "includes": [
        "加热、冷却过程中的传热传质及相变动力学理论",
        "微观组织（晶粒、相、析出相）演化规律及其对宏观性能的影响机制",
        "热处理缺陷（如变形、开裂）的力学与组织学成因及残余应力分布原理"
      ],
      "excludes": [
        "特定材料（如碳钢、铝合金）的具体热处理工艺曲线制定",
        "热处理生产线的设备选型、自动化控制或车间布局"
      ],
      "sibling_distinctions": [
        {
          "other_code": "N_f1b31e008e841b98",
          "rule": "本节点侧重普适性的物理冶金原理与动力学模型，兄弟节点侧重钢铁与有色合金的具体工艺实践（如退火、淬火的具体操作规范）。"
        },
        {
          "other_code": "N_d42b352141e934a6",
          "rule": "本节点侧重整体或局部的相变与组织演变理论，兄弟节点侧重通过元素扩散或局部加热改变表面成分与硬度的具体化学/物理工艺。"
        }
      ],
      "cross_boundary_rule": "涉及相变动力学计算时，若用于解释通用组织演变规律归本节点；若用于优化特定钢种的淬火冷却速度归钢铁与有色合金热处理节点。"
    },
    {
      "node_code": "N_f1b31e008e841b98",
      "definition": "针对钢铁及有色金属材料，研究退火、正火、淬火、回火、时效、固溶等常规及形变热处理工艺，旨在通过整体热循环优化材料综合力学性能。",
      "boundary": "聚焦于针对特定材料体系（钢、铝、钛等）的整体热处理工艺设计与实施，包括工艺参数选择、相变利用及形变与热处理的耦合。不包含仅改变表面成分或硬度的化学热处理（如渗碳），也不涉及纯理论推导或设备设计。",
      "includes": [
        "钢铁材料的退火、正火、淬火、回火工艺及其组织性能关系",
        "有色金属的固溶处理、时效处理及沉淀强化工艺",
        "形变热处理（如热机械处理）及控轧控冷工艺"
      ],
      "excludes": [
        "以改变表面化学成分或形成硬化层为目的的渗碳、渗氮等化学热处理",
        "热处理原理的纯数学建模或相变动力学的通用理论推导"
      ],
      "sibling_distinctions": [
        {
          "other_code": "N_46fe45aebea7ade5",
          "rule": "本节点侧重具体材料（钢/有色）的工艺应用与参数控制，兄弟节点侧重支撑这些工艺的通用物理冶金原理与动力学理论。"
        },
        {
          "other_code": "N_d42b352141e934a6",
          "rule": "本节点侧重材料整体性能的提升（如整体淬火、整体时效），兄弟节点侧重表面局部改性（如表面淬火、渗碳），二者在“整体”与“表面”的作用范围上区分。"
        }
      ],
      "cross_boundary_rule": "涉及“淬火”时，若为整体淬火以调整心部组织归本节点；若为感应/激光表面淬火以硬化表层归表面与化学热处理节点。"
    },
    {
      "node_code": "N_d42b352141e934a6",
      "definition": "研究通过元素扩散、局部加热或表面合金化等手段改变材料表层成分、组织与性能的技术，涵盖渗碳、渗氮、感应淬火及表面硬化层控制。",
      "boundary": "聚焦于材料表面（浅层）的改性，核心特征是改变表层化学成分或形成独立的硬化/功能层。包括化学热处理（渗碳、氮、硼等）和物理表面热处理（感应、火焰、激光）。不涉及材料整体心部的组织调整，也不涉及纯物理沉积涂层（如PVD/CVD，归表面工程）。",
      "includes": [
        "渗碳、渗氮、碳氮共渗等化学热处理工艺及渗层控制",
        "感应、火焰、激光等局部加热表面淬火工艺",
        "表面合金化、脱碳控制及有效硬化深度的测定与优化"
      ],
      "excludes": [
        "以改变材料整体心部组织为目的的整体退火、淬火或时效处理",
        "通过物理气相沉积（PVD）或化学气相沉积（CVD）形成的独立薄膜涂层"
      ],
      "sibling_distinctions": [
        {
          "other_code": "N_f1b31e00841b98",
          "rule": "本节点侧重表面局部改性（成分或硬度变化），兄弟节点侧重整体性能优化；例如，渗碳归本节点，整体调质归兄弟节点。"
        },
        {
          "other_code": "N_46fe45aebea7ade5",
          "rule": "本节点侧重具体的表面改性工艺技术与效果，兄弟节点侧重这些工艺背后的扩散动力学与相变理论原理。"
        }
      ],
      "cross_boundary_rule": "涉及“表面硬化”时，若通过元素扩散（如渗碳）或局部相变（如感应淬火）改变基体表层归本节点；若通过喷涂或沉积形成非基体材料层归表面工程与涂层节点。"
    }
  ]
}
